// supermanEyeAnchors.js
// Per-frame EYE ANCHORS for Superman — so Heat Vision fires from his actual eyes on every pose, not a
// fixed body-box fraction. Generated by superman_work/eye_detect.py (head/skin detection on each frame of
// each superman_*_uniform strip), stored as [ex, ey] FRACTIONS of the sprite cell (0..1, source art faces
// RIGHT). getSupermanEyeWorld() maps the current rendered frame's anchor to world space using the real
// drawn rect (_lastDrawX/Y/W/H set by sprite.js), mirroring for facing. Reusable blueprint for Homelander.
export const SUPERMAN_EYES = {
  idle:       [[0.588, 0.201], [0.693, 0.187]],
  walk:       [[0.820, 0.214], [0.581, 0.198], [0.605, 0.175]],
  crouch:     [[0.683, 0.202]],
  light:      [[0.512, 0.198], [0.700, 0.230]],   // fr1 jab windup (face), fr2 extended → keep eye near head height
  heavy:      [[0.596, 0.227], [0.700, 0.233]],
  uppercut:   [[0.573, 0.283], [0.552, 0.183]],
  air:        [[0.596, 0.227], [0.700, 0.233]],
  sweep:      [[0.507, 0.202], [0.507, 0.250]],
  flightdash: [[0.560, 0.709]],
  jump:       [[0.735, 0.204], [0.629, 0.176]],
  fall:       [[0.628, 0.181], [0.628, 0.210]],
  flight:     [[0.628, 0.181], [0.628, 0.210], [0.628, 0.225]],
  flycruise:  [[0.839, 0.237]],
  flightrise: [[0.703, 0.176]],
  flyturn:    [[0.633, 0.161]],
  land:       [[0.633, 0.331], [0.695, 0.305]],
  beam:       [[0.742, 0.235], [0.695, 0.189]],
  hurt:       [[0.507, 0.225]],
  guard:      [[0.694, 0.216]],
  cardboard:  [[0.699, 0.292], [0.596, 0.331], [0.591, 0.268]],
}

// current animation key → which strip's anchors to read (keys that share a sheet share anchors).
const ACTION_TO_STRIP = {
  idle: "idle", walk: "walk", run: "walk", dash: "walk", jump: "jump", fall: "fall",
  crouch: "crouch", hurt: "hurt", block: "guard", guard: "guard", charge: "beam",
  light: "light", heavy: "heavy", up: "uppercut", air: "air", sweep: "sweep",
  down_air: "flightdash", heatCharge: "beam", beam: "beam", dive: "flightdash",
  ultimate: "cardboard", flyHover: "flight", flyCruise: "flycruise", flyRise: "flightrise",
  flyDive: "flightdash", flyTurn: "flyturn", flyDash: "flightdash", takeoff: "jump", land: "land",
}

// World-space eye position for Superman's CURRENT rendered frame. Uses the real drawn rect cached by
// sprite.js (_lastDrawX/Y/W/H) so it tracks scale + offset; mirrors ex for a left-facing (flipped) draw.
export function getSupermanEyeWorld(fighter) {
  const face = fighter.facing || 1
  let ex = 0.64, ey = 0.19
  const sh = fighter.spriteHandler
  if (sh) {
    const strip = ACTION_TO_STRIP[sh.currentAction]
    const arr = strip && SUPERMAN_EYES[strip]
    if (arr && arr.length) {
      const fi = Math.max(0, Math.min(arr.length - 1, sh.frameIndex || 0))
      ex = arr[fi][0]; ey = arr[fi][1]
    }
  }
  const L = fighter._lastDrawX, W = fighter._lastDrawW, T = fighter._lastDrawY, H = fighter._lastDrawH
  if (L == null || !W || T == null || !H) {   // not drawn yet → body-box approximation
    return { x: fighter.x + (fighter.w || 50) * (face >= 0 ? 0.70 : 0.30), y: fighter.y + (fighter.h || 100) * 0.18 }
  }
  const x = face >= 0 ? L + ex * W : L + (1 - ex) * W
  const y = T + ey * H
  return { x, y }
}
